import{Module}from'../../core/index.js';import{THREE,materials,mesh,ringY}from'./geometry.js';
/** Exact own U128 supplied ordinary SMA-male accessory in the observed straight pose;dimension estimates,no invented hinge. */
export class Antenna extends Module{static meta={id:'m5stack.unit.catm.antenna',name:'Unit CatM supplied static straight antenna',sku:'U128 accessory',connector:'sma-female',physicalConnector:'sma-male'};build(){const frame=new THREE.Group();frame.name='CatM U128 own supplied static straight antenna';this.body.add(frame);const black=materials.plastic(0x191d19,{roughness:.72}),tin=materials.metal(0xaeb5a5,{roughness:.45}),gold=materials.metal(0xc3ab46,{roughness:.45}),coupling=ringY(frame,4.7,3.3,9,-3.2,black,'CatM supplied antenna actual open coupling sleeve'),thread=ringY(frame,3.29,3.25,5.2,-2.5,tin,'CatM supplied antenna recessed ordinary female-thread wall'),dielectric=ringY(frame,2.5,.29,3.8,2.8,materials.plastic(0xe8e7d1),'CatM supplied antenna actual bored dielectric'),pin=mesh(frame,new THREE.CylinderGeometry(.24,.24,7.8,32),gold,[0,.8,0],'CatM supplied antenna actual SMA-male centre pin'),neck=mesh(frame,new THREE.CylinderGeometry(3.75,4,17,48),black,[0,13,0],'CatM supplied antenna closed straight connector neck'),base=mesh(frame,new THREE.CylinderGeometry(3.7,3.75,9,48),black,[0,25,0],'CatM supplied antenna fixed observed moulded transition'),rod=mesh(frame,new THREE.CylinderGeometry(2.7,3.7,75.5,48),black,[0,67.25,0],'CatM supplied antenna fixed tapered rubber whip'),tip=mesh(frame,new THREE.SphereGeometry(2.7,32,20),black,[0,105,0],'CatM supplied antenna rounded closed tip');const ribs=[];for(let i=0;i<36;i++){const a=i*Math.PI*2/36;ribs.push(mesh(frame,new THREE.BoxGeometry(.22,6.8,.22),black,[Math.cos(a)*4.68,1.3,Math.sin(a)*4.68],'CatM supplied antenna fixed grip rib'));}const collars=[];for(const y of[19.5,28.8])collars.push(mesh(frame,new THREE.TorusGeometry(3.74,.1,8,48).rotateX(Math.PI/2),black,[0,y,0],'CatM supplied antenna fixed moulded collar'));this.antennaAssembly={frame,coupling,thread,dielectric,pin,neck,base,rod,tip,ribs,collars};}}
